#!/bin/bash
# RPD-RECO data-free prologue, rerun 3 (the director's go to prepare, 2026-11-08: #848 round 1 GO at combined head
# 2ed446b4, coverage-5b-audit). Its purpose is to record the worker's real key-level environment diff. The guard is
# expected to STOP again, now writing prologue-worker.STOP.json with the diff. Login node, 0 node-h, fresh clone, the
# real MAT source, the traced worker, no analysis input read, no flux connect.
# In this connect, in order:
#   1. the COV2D fence: every josephrb job must be named rs1_* or ens1_*; cov2d-* or any other name refuses;
#   2. the fresh clone's HEAD and porcelain;
#   3. the policy config, written from this script and checked against its sha256. It is #881's fe1ce783 with only
#      the clone root changed (prologue2-20261107 -> prologue3-20261108); the five repo pins it names are unchanged
#      at 2ed446b4;
#   4. the strace probe;
#   5. the prologue wrapper at 2ed446b4, unchanged since #881;
#   6. the redaction: redact_prepare.py writes run/prologue-prepare.view.json from the raw prologue-prepare.json,
#      which holds unsalted SHA-256 fingerprints of every environment value; check_redaction.py checks the view and
#      every other file bound for the repo against the raw fingerprints. Both scripts are written from this script
#      and checked against their sha256, and run under MAT_PYTHON -I -S;
#   7. only if the check passes: a base64 tar of an explicit file list, which never names prologue-prepare.json.
# umask 077: the root, the run directory and the raw record are readable by josephrb only. The root
# /dev/shm/limres-rpd-prologue3-20261108 is refused if it exists, and it is left in place: the raw record is deleted
# on the cluster after the receipt merges, under a ledger row, by a separate connect. Launched from a /dev/shm copy
# of itself ($1), which it deletes.
umask 077
SELF=$1
S=2ed446b4ba78269565ee1104462fc9e15b63afba
CFG_SHA=6c60de0b6077c593b3e221c6b39706633e09ae24eda54e65adc3fb21445a9bea
REDACT_SHA=5be4650d281d4eb896e94ea74ac74172cbe5beb6df56437351b701d5b108c6c8
CHECK_SHA=df244a49b46b13797b32f583cbed6ca48cf9df03f4c4c8a9e16e1ccf9526a8ad
MAT_PYTHON=/global/homes/j/josephrb/.conda/envs/root_6_28/bin/python3
R=/dev/shm/limres-rpd-prologue3-20261108
finish() { echo "== rpd-prologue3 rc=$1 $(date -u +%FT%TZ)"; rm -f -- "$SELF"; exit "$1"; }
case "$(hostname)" in login*) ;; *) echo "STOP: not a login node: $(hostname)"; finish 9 ;; esac
[ ! -e /dev/shm/limres-rpd-prologue3-20261108 ] || { echo "STOP: /dev/shm/limres-rpd-prologue3-20261108 exists"; finish 9; }
echo "node $(hostname) $(date -u +%FT%TZ)"
echo "connect script sha256 $(sha256sum "$SELF" | cut -d' ' -f1)"
echo "== 1. COV2D fence (allowed names: rs1_* and ens1_*; anything else refuses)"
fence=$(squeue -u josephrb -h -o '%i|%j|%T|%M|%l'); frc=$?
echo "squeue rc=$frc; rows:"
printf '%s\n' "$fence"
echo "-- end rows"
bad=$(printf '%s\n' "$fence" | awk -F'|' 'NF && $2 !~ /^(rs1_|ens1_)/')
echo "refusing rows: [$bad]"
[ "$frc" -eq 0 ] && [ -z "$bad" ] || { echo "STOP: the fence is not clear"; finish 3; }
echo "FENCE: clear"
mkdir -m 700 /dev/shm/limres-rpd-prologue3-20261108 || finish 9
echo "== 2. fresh clone at $S"
git clone --quiet --filter=blob:none --no-checkout https://github.com/josephbaileyy/MINERvA-OmniFold.git "$R/repo" || { echo "STOP: clone failed"; finish 5; }
git -C "$R/repo" -c advice.detachedHead=false checkout --quiet "$S" || { echo "STOP: checkout failed"; finish 5; }
head=$(git -C "$R/repo" rev-parse HEAD)
porc=$(git -C "$R/repo" status --porcelain | wc -l)
echo "HEAD $head; porcelain lines $porc"
[ "$head" = "$S" ] && [ "$porc" -eq 0 ] || { echo "STOP: the clone is not $S clean"; finish 5; }
for f in nd-unfolding/fd_rpd_reco_prologue_connect.sh nd-unfolding/fd_rpd_reco_prologue.py nd-unfolding/fd_rpd_reco.py nd-unfolding/fd_rpd_reco_custody.py nd-unfolding/fd_rpd_inputs.py; do
  echo "blob $(git -C "$R/repo" rev-parse "$S:$f") sha256 $(sha256sum "$R/repo/$f" | cut -d' ' -f1) $f"
done
echo "== 3. the policy config and the redaction scripts"
mkdir "$R/tools" || finish 9
printf '%s' '' | base64 -d > "$R/policy-config.json"
printf '%s' '' | base64 -d > "$R/tools/redact_prepare.py"
printf '%s' '' | base64 -d > "$R/tools/check_redaction.py"
for pair in "$R/policy-config.json:$CFG_SHA" "$R/tools/redact_prepare.py:$REDACT_SHA" "$R/tools/check_redaction.py:$CHECK_SHA"; do
  f=${pair%%:*}; want=${pair##*:}; got=$(sha256sum "$f" | cut -d' ' -f1)
  echo "sha256 $got (expected $want) $f"
  [ "$got" = "$want" ] || { echo "STOP: digest of $f"; finish 5; }
done
echo "== 4. strace probe"
/usr/bin/strace -f -e trace=open,openat,openat2 -o "$R/strace-probe.txt" /bin/true
echo "strace probe rc=$? lines $(wc -l < "$R/strace-probe.txt")"
echo "== 5. the prologue: bash fd_rpd_reco_prologue_connect.sh CHECKOUT CONFIG SHA RUN MAT_PYTHON"
bash "$R/repo/nd-unfolding/fd_rpd_reco_prologue_connect.sh" "$R/repo" "$R/policy-config.json" "$CFG_SHA" "$R/run" "$MAT_PYTHON"
p=$?
echo "prologue wrapper rc=$p"
echo "== run directory (sha256 of every file, the raw record included)"
find "$R/run" -maxdepth 1 -type f -printf '%m %s %P\n' 2>&1 | sort -k3
for f in "$R"/run/*; do [ -f "$f" ] && echo "sha256 $(sha256sum "$f" | cut -d' ' -f1) ${f#$R/}"; done
[ -f "$R/run/prologue-prepare.json" ] || { echo "STOP: no raw prepare record; nothing to redact"; finish 6; }
echo "== 6. redaction"
stop=NONE; [ -f "$R/run/prologue-worker.STOP.json" ] && stop="$R/run/prologue-worker.STOP.json"
echo "worker STOP record: $stop"
"$MAT_PYTHON" -I -S "$R/tools/redact_prepare.py" "$R/run/prologue-prepare.json" "$stop" "$R/run/prologue-prepare.view.json" > "$R/run/redact.out" 2>&1
rrc=$?
cat "$R/run/redact.out"; echo "redact rc=$rrc"
[ "$rrc" -eq 0 ] || { echo "STOP: redaction failed"; finish 6; }
send=(strace-probe.txt run/trace-policy.json run/prologue.strace run/worker.stderr.txt run/worker.stdout.txt run/prologue-prepare.view.json run/redact.out run/redaction-check.txt)
for f in run/prologue-worker.STOP.json run/prologue-worker.json run/data-free-trace.json; do [ -f "$R/$f" ] && send+=("$f"); done
checked=()
for f in "${send[@]}"; do case "$f" in run/prologue-prepare.view.json|run/redaction-check.txt) ;; *) checked+=("$R/$f") ;; esac; done
checked+=("$R/policy-config.json")
"$MAT_PYTHON" -I -S "$R/tools/check_redaction.py" "$R/run/prologue-prepare.json" "$R/run/prologue-prepare.view.json" "${checked[@]}" > "$R/run/redaction-check.txt" 2>&1
crc=$?
cat "$R/run/redaction-check.txt"; echo "check rc=$crc"
[ "$crc" -eq 0 ] || { echo "STOP: the redaction check did not pass; nothing is sent"; finish 7; }
echo "== 7. files sent (explicit list)"
for f in "${send[@]}"; do
  case "$f" in *prologue-prepare.json) echo "STOP: the raw record is on the send list"; finish 7 ;; esac
  echo "sha256 $(sha256sum "$R/$f" | cut -d' ' -f1) $f"
done
echo "== TAR BEGIN"
tar -C "$R" -cf - "${send[@]}" | base64 -w 76
echo "== TAR END tar rc=${PIPESTATUS[0]}"
echo "left in place for the post-merge deletion: $R (raw record run/prologue-prepare.json)"
finish "$p"
